    var result;

    $.ajax({
        url: '...',
        success: function(response) {
            result = response;
            // return response; // Example using Node.js:

```
function foo() {
    var result;

    fs.readFile("path/to/file", function(err, data) {
        result = data;
        // return data; // Example using the `then` block of a promise:

```
function foo() {
